const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const alive = JSON.parse(await fs.readFile(S+"\\_GIG_ALL_ALIVE.json","utf8"));

// 按根域名去重
const domainOf = h => {
  const x = String(h).toLowerCase().replace(/^www\./,"");
  const parts = x.split(".");
  if (parts.length <= 2) return x;
  // 处理 co.uk / com.au / co.jp 等
  const tld2 = parts.slice(-2).join(".");
  if (/^(co|com|net|org|gov|ac|edu)\.[a-z]{2}$/.test(tld2)) return parts.slice(-3).join(".");
  return tld2;
};

const byDomain = {};
for (const a of alive) {
  const d = domainOf(a.host);
  (byDomain[d] ??= []).push(a.name+" ["+a.verdict.replace(/[✅🟡]/g,'').trim()+"] "+a.host);
}
const domains = Object.keys(byDomain);
return {
  totalEntries: alive.length,
  uniqueDomains: domains.length,
  duplicates: Object.entries(byDomain).filter(([d,v])=>v.length>1),
  domainList: domains
};
